// DINOSAURS EXPANSION — 25 questions per grade (grades 1-5)
// Merge into graded-questions.js under "Dinosaurs" > each grade

const DINOSAURS_EXPANSION = {
  "1st Grade": [
    {q:"What do we call scientists who study dinosaurs?",correct:"Paleontologists",options:["Zoologists","Paleontologists","Biologists","Astronomers"],fact:"Paleontologists use fossils — preserved bones, teeth, and footprints — to learn how dinosaurs lived millions of years ago."},
    {q:"Which dinosaur had the longest neck?",correct:"Brachiosaurus",options:["T-Rex","Brachiosaurus","Triceratops","Stegosaurus"],fact:"Brachiosaurus could reach leaves over 30 feet high — taller than a two-story building!"},
    {q:"What is a fossil?",correct:"Preserved remains or traces of an ancient living thing",options:["A glowing rock","Preserved remains or traces of an ancient living thing","A dinosaur egg","A dinosaur model"],fact:"Fossils can be bones, teeth, footprints, or even poop (called coprolites)!"},
    {q:"Which dinosaur had three horns on its face?",correct:"Triceratops",options:["Stegosaurus","T-Rex","Triceratops","Brachiosaurus"],fact:"Triceratops used its three horns to defend itself against predators like T-Rex."},
    {q:"Were dinosaurs alive at the same time as humans?",correct:"No — dinosaurs went extinct millions of years before humans appeared",options:["Yes, we lived together","No — dinosaurs went extinct millions of years before humans appeared","Yes, but only small ones","No — humans came first"],fact:"Non-bird dinosaurs went extinct 66 million years ago. The earliest humans appeared only about 300,000 years ago."},
    {q:"What did plant-eating dinosaurs eat?",correct:"Leaves, ferns, and other plants",options:["Meat and fish","Leaves, ferns, and other plants","Insects only","Seeds only"],fact:"Plant-eating dinosaurs are called herbivores. They had flat teeth perfect for grinding plants."},
    {q:"What do dinosaur footprints tell scientists?",correct:"How fast a dinosaur moved and how big it was",options:["Nothing useful","How fast a dinosaur moved and how big it was","What color it was","How smart it was"],fact:"Some dinosaur footprints are so big that a child could sit inside them like a bathtub!"},
    {q:"Which dinosaur had bony plates along its back?",correct:"Stegosaurus",options:["T-Rex","Stegosaurus","Velociraptor","Diplodocus"],fact:"Stegosaurus's brain was about the size of a walnut — tiny for such a large animal!"},
    {q:"Where have dinosaur fossils been found?",correct:"On every continent, including Antarctica",options:["Only in Africa","Only in America","On every continent, including Antarctica","Only in hot places"],fact:"Antarctica was once warm enough for dinosaurs! Scientists have found fossils there from hundreds of millions of years ago."},
    {q:"What are baby dinosaurs hatched from?",correct:"Eggs",options:["Live like mammals","Eggs","Pouches","Pods"],fact:"Some dinosaur eggs were as big as a football, while others were no bigger than a chicken egg."},
    {q:"What does the word 'carnivore' mean?",correct:"An animal that eats meat",options:["An animal that eats plants","An animal that eats meat","An animal that eats both","An animal that eats rocks"],fact:"T-Rex was one of the most famous carnivores — it could eat 500 pounds of meat in one bite!"},
    {q:"What modern animals are dinosaurs most closely related to?",correct:"Birds",options:["Lizards","Crocodiles","Birds","Snakes"],fact:"Scientists discovered that birds evolved from small feathered dinosaurs — so technically, chickens are dinosaur descendants!"},
    {q:"Which dinosaur ran on two legs and was about the size of a turkey?",correct:"Velociraptor",options:["Brachiosaurus","Velociraptor","Triceratops","Ankylosaurus"],fact:"Real Velociraptors were much smaller than in Jurassic Park movies — about the size of a large turkey!"},
    {q:"What might have caused the dinosaurs to go extinct?",correct:"A huge asteroid hitting Earth",options:["They ran out of water","A huge asteroid hitting Earth","A giant flood","They all got sick at once"],fact:"The asteroid that hit Earth 66 million years ago caused fires, darkness, and cold that wiped out most life on the planet."},
    {q:"What does the word 'herbivore' mean?",correct:"An animal that only eats plants",options:["An animal that eats meat","An animal that eats both","An animal that only eats plants","An animal that eats insects"],fact:"Many of the biggest dinosaurs were herbivores — giant sauropods needed to eat huge amounts of plants every single day!"},
    {q:"Which dinosaur had a dome-shaped head used for head-butting?",correct:"Pachycephalosaurus",options:["Triceratops","Pachycephalosaurus","Ankylosaurus","Stegosaurus"],fact:"Pachycephalosaurus had a skull up to 10 inches thick — it could ram other dinosaurs like a battering ram!"},
    {q:"What is the Mesozoic Era?",correct:"The time period when dinosaurs lived on Earth",options:["When humans lived","The time period when dinosaurs lived on Earth","The time of ice ages","The future"],fact:"The Mesozoic Era lasted about 186 million years and is divided into the Triassic, Jurassic, and Cretaceous periods."},
    {q:"Which time period did T-Rex live in?",correct:"Cretaceous",options:["Jurassic","Triassic","Cretaceous","Permian"],fact:"T-Rex lived about 68–66 million years ago, near the very end of the Cretaceous period."},
    {q:"What did Ankylosaurus use to defend itself?",correct:"A bony tail club it could swing at predators",options:["Sharp teeth","A bony tail club it could swing at predators","Poison","Very loud roars"],fact:"Ankylosaurus's tail club could break bones — even those of T-Rex! It was like a living tank."},
    {q:"What does the word 'dinosaur' mean?",correct:"Terrible lizard",options:["Giant beast","Terrible lizard","Ancient creature","Stone animal"],fact:"The name 'dinosaur' was invented by scientist Richard Owen in 1842, from Greek words meaning 'terrifying lizard.'"},
    {q:"What is the name for a dinosaur that walked on four legs?",correct:"Quadrupedal",options:["Bipedal","Quadrupedal","Hexapodal","Tripedal"],fact:"Large sauropods like Brachiosaurus were quadrupedal — all four legs supported their enormous bodies like pillars."},
    {q:"What is an omnivore?",correct:"An animal that eats both plants and meat",options:["An animal that eats only plants","An animal that eats only meat","An animal that eats both plants and meat","An animal that eats insects only"],fact:"Oviraptor was an omnivore dinosaur that ate plants, eggs, and small animals."},
    {q:"Which dinosaur had the largest meat-eating body ever found?",correct:"Spinosaurus",options:["T-Rex","Velociraptor","Spinosaurus","Allosaurus"],fact:"Spinosaurus was longer than T-Rex — over 50 feet — and probably hunted fish in rivers and swamps."},
    {q:"What was special about Pterodactyls?",correct:"They could fly, but they were not actually dinosaurs",options:["They breathed fire","They could fly, but they were not actually dinosaurs","They lived underwater","They had six legs"],fact:"Pterodactyls were flying reptiles called pterosaurs — closely related to dinosaurs but a separate group."},
    {q:"What is a coprolite?",correct:"Fossilized dinosaur poop",options:["A dinosaur claw","Fossilized dinosaur poop","A type of rock","A dinosaur egg"],fact:"Coprolites can contain fish bones, plant material, or bone fragments — telling scientists exactly what a dinosaur had for its last meal!"},
  ],
  "2nd Grade": [
    {q:"What is the difference between Saurischian and Ornithischian dinosaurs?",correct:"Saurischians had lizard-like hips; Ornithischians had bird-like hips",options:["Size only","Saurischians had lizard-like hips; Ornithischians had bird-like hips","Diet only","Leg shape only"],fact:"Surprisingly, birds actually evolved from Saurischian (lizard-hipped) dinosaurs, not the bird-hipped Ornithischians!"},
    {q:"What are trace fossils?",correct:"Fossils of footprints, nests, or droppings rather than body parts",options:["Broken fossils","Fossils of footprints, nests, or droppings rather than body parts","Very tiny fossils","Fossils found in caves"],fact:"Trace fossils tell us how dinosaurs moved, where they nested, and even what they ate — without finding a single bone!"},
    {q:"How do scientists find out how old a fossil is?",correct:"By measuring the age of the rock layers where the fossil was found",options:["By counting rings in the bone","By measuring the age of the rock layers where the fossil was found","By the fossil's color","By how heavy it is"],fact:"This process is called radiometric dating. It uses radioactive elements that decay at known rates, acting like a natural clock in the rock."},
    {q:"What is Pangaea?",correct:"An ancient supercontinent where early dinosaurs first appeared",options:["A type of dinosaur","An ancient supercontinent where early dinosaurs first appeared","A prehistoric ocean","A type of rock"],fact:"When dinosaurs first evolved, all continents were joined as one supercontinent called Pangaea. As it broke apart, dinosaurs spread across the world!"},
    {q:"Which dinosaur had the longest tail?",correct:"Diplodocus, whose tail could be over 45 feet long",options:["Brachiosaurus","Apatosaurus","Diplodocus, whose tail could be over 45 feet long","T-Rex"],fact:"Diplodocus could crack its tail like a whip, making a sound like a cannon — probably used for communication or scaring predators!"},
    {q:"What was a sauropod?",correct:"A long-necked, four-legged plant-eating dinosaur",options:["A meat-eating dinosaur","A flying reptile","A long-necked, four-legged plant-eating dinosaur","An armored dinosaur"],fact:"Sauropods were the largest land animals that ever lived — some weighed as much as 10 large elephants combined!"},
    {q:"Why did many large dinosaurs have hollow bones?",correct:"Hollow bones made them lighter without losing much strength",options:["Their bones rotted out","Hollow bones made them lighter without losing much strength","To breathe through them","To store food"],fact:"Birds inherited hollow bones from their dinosaur ancestors — one reason birds can fly despite having large muscles and wings!"},
    {q:"What evidence suggests some dinosaurs cared for their young?",correct:"Fossilized nests with young dinosaurs and worn eggshells from hatchlings moving around",options:["No evidence exists","Fossilized nests with young dinosaurs and worn eggshells from hatchlings moving around","Adult bones near nests","Written records"],fact:"Maiasaura (meaning 'good mother lizard') is famous for this — fossilized nests showed babies stayed and were fed after hatching!"},
    {q:"What do gastroliths tell scientists about dinosaurs?",correct:"That some dinosaurs swallowed stones to grind food in their stomachs",options:["That dinosaurs ate rocks","That some dinosaurs swallowed stones to grind food in their stomachs","That dinosaurs lived near rivers","Nothing useful"],fact:"Many modern birds like ostriches and chickens still swallow small stones called grit to help grind up their food — a habit inherited from dinosaur ancestors!"},
    {q:"What was the Triassic period known for regarding dinosaurs?",correct:"It's when dinosaurs first evolved, about 230 million years ago",options:["When dinosaurs went extinct","It's when dinosaurs first evolved, about 230 million years ago","When T-Rex appeared","When birds evolved"],fact:"The very first dinosaurs were small, two-legged creatures. They became dominant only after a mass extinction wiped out their competitors."},
    {q:"Why are birds considered living dinosaurs?",correct:"Birds evolved directly from small feathered theropod dinosaurs",options:["They're not related","Birds evolved directly from small feathered theropod dinosaurs","Birds evolved from pterosaurs","Only ostriches are dinosaurs"],fact:"Archaeopteryx, found in Germany, is a famous fossil showing the transition between feathered dinosaurs and modern birds — it had both feathers and dinosaur claws!"},
    {q:"What was the largest flying pterosaur?",correct:"Quetzalcoatlus, with a wingspan as wide as a small airplane",options:["Pterodactylus","Rhamphorhynchus","Quetzalcoatlus, with a wingspan as wide as a small airplane","Dimorphodon"],fact:"Quetzalcoatlus was the size of a giraffe when standing! Its wingspan stretched about 36 feet across — wider than many small planes."},
    {q:"How do we know some dinosaurs had feathers?",correct:"Fossils from China preserve detailed feather impressions on small theropod dinosaurs",options:["We don't know","Fossils from China preserve detailed feather impressions on small theropod dinosaurs","From cave paintings","All dinosaurs had feathers"],fact:"Fossil sites in China's Yixian Formation have produced hundreds of beautifully preserved feathered dinosaur fossils since the 1990s!"},
    {q:"What is the Morrison Formation important for?",correct:"It's a rock formation in the American West containing many famous Jurassic dinosaur fossils",options:["It's in Africa","It's a rock formation in the American West containing many famous Jurassic dinosaur fossils","It only has plant fossils","It was discovered in 2020"],fact:"The Morrison Formation produced famous dinosaurs like Allosaurus, Stegosaurus, and Diplodocus — all from the same time and place about 150 million years ago!"},
    {q:"What is Gondwana?",correct:"An ancient southern supercontinent that eventually became South America, Africa, Australia, and Antarctica",options:["A type of dinosaur","A prehistoric sea","An ancient southern supercontinent that eventually became South America, Africa, Australia, and Antarctica","A modern country"],fact:"Because of Gondwana, very similar dinosaur fossils are found in South America and Africa — those continents were once connected and shared the same animals!"},
    {q:"Which Cretaceous dinosaur is called the 'good mother lizard'?",correct:"Maiasaura, because it cared for its young in nests",options:["T-Rex","Triceratops","Maiasaura, because it cared for its young in nests","Velociraptor"],fact:"Maiasaura nests were discovered in Montana filled with babies — strong evidence these dinosaurs raised their young, much like birds and crocodilians today."},
    {q:"What was special about Therizinosaurus?",correct:"It had the longest claws of any known land animal — up to 3 feet long",options:["It was tiny","It had the longest claws of any known land animal — up to 3 feet long","It could fly","It lived underwater"],fact:"Despite its terrifying claws, Therizinosaurus was likely an herbivore that used them to pull down branches and leaves to eat!"},
    {q:"Which dinosaur had the smallest brain compared to its body size?",correct:"Stegosaurus",options:["T-Rex","Velociraptor","Stegosaurus","Triceratops"],fact:"Stegosaurus's brain was only about the size of a dog's brain — yet its body was as long as a bus! It mostly relied on instinct rather than intelligence."},
    {q:"What is biomechanics and how is it used in dinosaur research?",correct:"Studying how dinosaur muscles and bones worked together to understand how they moved",options:["A type of fossil","Studying dinosaur diets","Studying how dinosaur muscles and bones worked together to understand how they moved","A computer game about dinosaurs"],fact:"By studying biomechanics, scientists estimated T-Rex walked at about 12 mph — faster than most humans run!"},
    {q:"What were pack hunters?",correct:"Dinosaurs that hunted in groups to take down larger prey",options:["Solo hunters","Dinosaurs that hunted in groups to take down larger prey","Plant-eating dinosaurs","Very large dinosaurs"],fact:"Deinonychus fossils have been found alongside large prey animals, suggesting these small predators worked as a team — like wolves hunting elk today."},
    {q:"What is Jurassic Park about?",correct:"A movie about scientists bringing dinosaurs back to life using ancient DNA",options:["A real dinosaur park","A movie about scientists bringing dinosaurs back to life using ancient DNA","A zoo with real dinosaurs","A museum tour"],fact:"While Jurassic Park is fictional, scientists have found some preserved soft tissue in dinosaur bones — though recovering usable DNA to clone a dinosaur remains impossible with current science."},
    {q:"Why did sauropods need to eat so much every day?",correct:"Their enormous bodies required massive amounts of plant material just to stay alive",options:["They were always hungry","Their enormous bodies required massive amounts of plant material just to stay alive","They ate for fun","They stored food in their tails"],fact:"A large sauropod might have needed to eat several hundred pounds of plants per day — spending most of its waking hours just eating to fuel its massive body!"},
    {q:"What does it mean if a dinosaur was bipedal?",correct:"It walked on two legs",options:["It swam underwater","It walked on two legs","It could fly","It had two heads"],fact:"T-Rex, Velociraptor, and most meat-eating dinosaurs were bipedal. Their tiny front arms were freed up because their powerful back legs did all the walking!"},
    {q:"How did hadrosaurs (duck-billed dinosaurs) communicate?",correct:"Many had hollow crests on their heads that may have made sounds like a horn",options:["They talked like humans","Many had hollow crests on their heads that may have made sounds like a horn","They couldn't communicate","They wrote messages in dirt"],fact:"Parasaurolophus had a hollow crest up to 6 feet long that scientists think could produce deep, resonating sounds to call to the herd or warn of danger!"},
    {q:"What is the biggest difference between a dinosaur and a modern lizard?",correct:"Dinosaurs had legs positioned directly under their bodies; lizards have legs that sprawl out to the sides",options:["Size only","Dinosaurs had legs positioned directly under their bodies; lizards have legs that sprawl out to the sides","Dinosaurs could breathe fire","Lizards are smaller versions of dinosaurs"],fact:"This upright stance gave dinosaurs a huge advantage in speed and endurance — it's the same feature that makes birds, mammals, and crocodilians better movers than modern lizards!"},
  ],
  "3rd Grade": [
    {q:"What is cladistics and how is it used in dinosaur classification?",correct:"A method of grouping organisms by shared evolutionary characteristics from a common ancestor",options:["A fossil dating method","A method of grouping organisms by shared evolutionary characteristics from a common ancestor","A type of bone analysis","A digging method"],fact:"Cladistics revealed that birds are so closely related to theropods that birds ARE technically classified as dinosaurs in modern taxonomy!"},
    {q:"What does radiometric dating measure?",correct:"The age of rocks and fossils by measuring decay rates of radioactive isotopes",options:["The size of dinosaurs","The age of rocks and fossils by measuring decay rates of radioactive isotopes","What dinosaurs ate","The color of fossils"],fact:"Uranium-lead dating can measure ages in billions of years with remarkable accuracy — like reading a natural clock built into the rock."},
    {q:"How do bone histology studies help us understand dinosaur growth?",correct:"Thin slices of bone examined under microscopes reveal annual growth rings that show how fast and how long dinosaurs grew",options:["By measuring bone length only","Thin slices of bone examined under microscopes reveal annual growth rings that show how fast and how long dinosaurs grew","By counting teeth","By weighing bones"],fact:"Like tree rings, dinosaur bones show annual growth layers — studies show T-Rex reached near full size in just a few years, growing at an astonishing rate!"},
    {q:"What are the two main groups of dinosaurs based on hip structure?",correct:"Saurischia (lizard-hipped) and Ornithischia (bird-hipped)",options:["Big and small","Saurischia (lizard-hipped) and Ornithischia (bird-hipped)","Meat-eaters and plant-eaters","Fliers and walkers"],fact:"Ironically, despite being called 'bird-hipped,' Ornithischians like Triceratops are less closely related to birds than the 'lizard-hipped' Saurischians like T-Rex!"},
    {q:"What was the Cretaceous-Paleogene extinction event?",correct:"The mass extinction 66 million years ago that killed about 75% of all species including non-bird dinosaurs",options:["A small regional event","The mass extinction 66 million years ago that killed about 75% of all species including non-bird dinosaurs","A volcanic eruption only","An ice age only"],fact:"The Chicxulub asteroid impact near Mexico's Yucatán Peninsula triggered this extinction — the crater it left is over 100 miles wide and still visible from space today."},
    {q:"What is the significance of Archaeopteryx?",correct:"It is a transitional fossil showing features of both theropod dinosaurs and modern birds",options:["The first dinosaur ever","It is a transitional fossil showing features of both theropod dinosaurs and modern birds","The last dinosaur","Only a modern bird ancestor"],fact:"Found in Germany in 1861, Archaeopteryx had feathers and wings like a bird but also dinosaur features: teeth, clawed wings, and a long bony tail."},
    {q:"How did the breakup of Pangaea influence dinosaur evolution?",correct:"Isolated populations on different continents evolved independently, creating great diversity of dinosaur species worldwide",options:["It didn't matter","Isolated populations on different continents evolved independently, creating great diversity of dinosaur species worldwide","All dinosaurs stayed the same","Only a few species survived the split"],fact:"This is why you find very different dinosaur species in North America vs. South America vs. Africa vs. Asia — continental separation drove separate evolution!"},
    {q:"What is convergent evolution in the context of dinosaurs?",correct:"When unrelated dinosaurs independently evolved similar features because they faced similar environmental challenges",options:["When species split apart","When unrelated dinosaurs independently evolved similar features because they faced similar environmental challenges","When species hybridize","When fossils are found together"],fact:"Multiple completely different dinosaur lineages independently evolved thick skulls for head-butting — the same solution discovered separately by different evolutionary paths!"},
    {q:"What is taphonomy and why does it matter for paleontology?",correct:"The study of how organisms decay and become fossils, helping scientists interpret what fossil evidence actually means",options:["Studying large fossils only","The study of how organisms decay and become fossils, helping scientists interpret what fossil evidence actually means","Dating fossils only","Finding fossils"],fact:"Taphonomy tells us why some dinosaurs are well-known while others remain mysterious — it all depends on how and where their bones were buried and preserved."},
    {q:"What evidence showed that some theropods like Velociraptor had feathers?",correct:"Quill knobs on forearm bones indicate where wing feathers attached, just like in modern birds",options:["We still don't know","Quill knobs on forearm bones indicate where wing feathers attached, just like in modern birds","Only skin impressions exist","From preserved eggs"],fact:"Despite movie portrayals, real Velociraptors were feathered, turkey-sized predators — not the 6-foot scaly monsters of Hollywood!"},
    {q:"What is a nesting site and what have they revealed?",correct:"A place where dinosaurs laid and incubated eggs, revealing parental behavior and social habits",options:["A bird's nest only","A place where dinosaurs laid and incubated eggs, revealing parental behavior and social habits","A cave where dinosaurs slept","A river crossing"],fact:"Some hadrosaur nesting sites contain hundreds of nests together, suggesting these dinosaurs nested in large colonies — like modern seabirds!"},
    {q:"What was the ecological role of large sauropods?",correct:"Like modern elephants, they shaped landscapes by trampling vegetation and creating open areas used by other species",options:["They were apex predators","Like modern elephants, they shaped landscapes by trampling vegetation and creating open areas used by other species","They were harmless grazers","They lived in isolation"],fact:"A single sauropod herd moving through a forest would dramatically reshape the landscape — creating clearings, spreading seeds, and changing what other animals could live there."},
    {q:"What is island dwarfism in dinosaurs?",correct:"Dinosaurs isolated on ancient islands evolved smaller body sizes due to limited food resources",options:["Islands made dinosaurs bigger","Dinosaurs isolated on ancient islands evolved smaller body sizes due to limited food resources","Islands had no dinosaurs","Size never changed on islands"],fact:"Fossils from ancient Mediterranean islands show miniature sauropods only a few feet tall — evolution made them smaller because islands couldn't support giant animals."},
    {q:"What did protein analysis of T-Rex bones reveal?",correct:"Chemical signatures closely matching those of modern chickens and ostriches, confirming birds are living dinosaurs",options:["Nothing useful","Chemical signatures closely matching those of modern chickens and ostriches, confirming birds are living dinosaurs","That T-Rex was warm-blooded","That DNA could be recovered"],fact:"In 2007, collagen protein sequences from T-Rex bones were found to closely match chickens — a direct biochemical link between extinct dinosaurs and modern birds!"},
    {q:"What is the Deccan Traps and how did it relate to dinosaur extinction?",correct:"Massive volcanic eruptions in India that were already stressing ecosystems before the asteroid struck",options:["A dinosaur trap","A fossil site only","Massive volcanic eruptions in India that were already stressing ecosystems before the asteroid struck","A type of dinosaur"],fact:"Some scientists believe the combined effect of Deccan volcanism plus the asteroid impact made extinction unavoidable — a double catastrophe."},
    {q:"How did air sac systems in dinosaurs differ from modern reptile breathing?",correct:"Dinosaurs had a one-way airflow system like birds, making breathing far more efficient than modern reptiles",options:["They breathed the same way","Dinosaurs had a one-way airflow system like birds, making breathing far more efficient than modern reptiles","Dinosaurs breathed through skin","They had gill-like organs"],fact:"This efficient breathing system is why birds can fly at high altitudes where air is thin — inherited from dinosaur ancestors who needed high oxygen for active lifestyles!"},
    {q:"What were hadrosaur 'bone beds' and what do they suggest?",correct:"Huge accumulations of many individuals together, suggesting hadrosaurs migrated in large herds",options:["Hadrosaurs were solitary","Huge accumulations of many individuals together, suggesting hadrosaurs migrated in large herds","Only pairs lived together","No evidence of groups exists"],fact:"Some hadrosaur bonebeds contain thousands of individuals — evidence of massive herds like modern wildebeest migrations across the ancient plains!"},
    {q:"What is the significance of feathered dinosaur fossils from China's Yixian Formation?",correct:"They proved many dinosaurs had feathers and directly linked them to modern birds",options:["They showed dinosaurs could swim","They proved many dinosaurs had feathers and directly linked them to modern birds","They disproved evolution","They showed all dinosaurs were small"],fact:"Hundreds of exquisitely preserved specimens with feathers, soft tissue, and even color patterns have been discovered in China — transforming our understanding of dinosaurs!"},
    {q:"What do stomach contents preserved in fossils reveal?",correct:"Directly what a specific dinosaur individual was eating at the time of death",options:["Cannot be preserved","Directly what a specific dinosaur individual was eating at the time of death","Only plant diets","Only for large dinosaurs"],fact:"A Sinosauropteryx fossil preserved the remains of a lizard inside its stomach — a direct window to what this dinosaur ate 130 million years ago!"},
    {q:"How did sexual selection theory apply to ceratopsian horn evolution?",correct:"The great variety of horn and frill shapes within related species suggests they were used for species recognition and mate selection",options:["Horns were only for defense","The great variety of horn and frill shapes within related species suggests they were used for species recognition and mate selection","All ceratopsians had identical horns","Frills had no function"],fact:"Related ceratopsian species living in the same habitat had dramatically different frills and horns — making it easy to find a mate of the right species!"},
    {q:"What is paleoecology and what has it revealed about dinosaur communities?",correct:"The study of ancient ecosystems, showing dinosaurs lived in complex communities with distinct predator/prey/herbivore roles",options:["Studying ancient plants only","The study of ancient ecosystems, showing dinosaurs lived in complex communities with distinct predator/prey/herbivore roles","Studying ancient climate","Studying ancient seas"],fact:"Dinosaur communities were as complex as modern African savanna ecosystems — with multiple herbivore species, apex predators, scavengers, and everything in between!"},
    {q:"What makes the Morrison Formation unusually valuable for paleontology?",correct:"It's a Late Jurassic deposit in the American West with extraordinary diversity of dinosaurs from the same time period",options:["It's in Africa","It's a Late Jurassic deposit in the American West with extraordinary diversity of dinosaurs from the same time period","It only has plant fossils","It was discovered in 2020"],fact:"Allosaurus, Stegosaurus, Apatosaurus, and Diplodocus all came from the Morrison Formation — it's like a Jurassic time capsule of an entire ecosystem!"},
    {q:"What do isotope analyses of dinosaur teeth reveal?",correct:"Dietary patterns and migration routes by comparing isotopes in teeth to local water and plant sources",options:["Age of the dinosaur","Dietary patterns and migration routes by comparing isotopes in teeth to local water and plant sources","Speed of growth","Color of teeth"],fact:"Isotope studies showed some large dinosaurs migrated hundreds of miles seasonally — like modern African wildlife following rainfall and fresh vegetation!"},
    {q:"How does studying modern crocodilians help scientists understand dinosaur biology?",correct:"As close relatives of dinosaurs (along with birds), crocs share behavioral and physiological traits that help reconstruct dinosaur biology",options:["Crocs are unrelated","As close relatives of dinosaurs (along with birds), crocs share behavioral and physiological traits that help reconstruct dinosaur biology","Crocs only tell us about diets","Crocs are more related to mammals"],fact:"Crocodilians, birds, and dinosaurs all belong to Archosauria — a group with a common ancestor. Studying living archosaurs helps reconstruct what extinct ones were like!"},
    {q:"What is the current status of dinosaur discovery — are most species already known?",correct:"No — scientists estimate thousands of species remain to be discovered; dozens of new ones are named every year",options:["Yes, all are known","No — scientists estimate thousands of species remain to be discovered; dozens of new ones are named every year","Only a handful remain unknown","Discovery ended in the 20th century"],fact:"Over 1,000 dinosaur species have been named, but scientists estimate this represents only about 30% of all dinosaur species that actually lived — we are still in a golden age of discovery!"},
  ],
  "4th Grade": [
    {q:"What is phylogenetic systematics and how has it changed our view of dinosaurs?",correct:"A classification system based on evolutionary ancestry that revealed birds as living members of the dinosaur family tree",options:["A fossil-finding technique","A classification system based on evolutionary ancestry that revealed birds as living members of the dinosaur family tree","A geological dating method","A museum display system"],fact:"Before cladistics, scientists grouped animals by appearance. Evolution-based classification revealed that birds are not 'like dinosaurs' — they literally ARE dinosaurs."},
    {q:"What does an endocast of a dinosaur skull tell scientists?",correct:"The approximate size, shape, and structure of the dinosaur's brain, indicating sensory abilities and intelligence",options:["The dinosaur's diet only","The approximate size, shape, and structure of the dinosaur's brain, indicating sensory abilities and intelligence","The dinosaur's age only","Skin color"],fact:"T-Rex endocasts show huge olfactory bulbs — meaning its extraordinary sense of smell was likely its primary hunting tool, more important than its eyesight."},
    {q:"What is the impact of CT scanning on dinosaur paleontology?",correct:"It allows detailed internal examination of fossils without damage, revealing sinuses, brain cavities, and bone structure",options:["CT scanning isn't used in paleontology","It allows detailed internal examination of fossils without damage, revealing sinuses, brain cavities, and bone structure","It only shows external features","It colors fossils for display"],fact:"CT scans of dinosaur skulls revealed air-filled sinuses that reduced head weight — like a biological weight-saving engineering solution in giant skulls!"},
    {q:"How did ichthyosaurs and plesiosaurs differ from true dinosaurs?",correct:"They were marine reptiles that lived at the same time as dinosaurs but belonged to completely separate evolutionary lineages",options:["They were water-dwelling dinosaurs","They were marine reptiles that lived at the same time as dinosaurs but belonged to completely separate evolutionary lineages","They were amphibians","They were fish ancestors"],fact:"Ichthyosaurs and plesiosaurs evolved from land reptiles that returned to the sea — similar to how whales evolved from land mammals millions of years later!"},
    {q:"What does biomechanical analysis reveal about T-Rex's bite force?",correct:"Skull bones and muscle attachment points indicate a bite force up to 12,800 pounds — the strongest of any known land animal",options:["It had a weak bite","Skull bones and muscle attachment points indicate a bite force up to 12,800 pounds — the strongest of any known land animal","Its bite was average","Bite force cannot be calculated from fossils"],fact:"T-Rex could crush bone with its bite — paleontologists have found Triceratops bones with T-Rex tooth marks punched completely through solid bone!"},
    {q:"What does isotope analysis of dinosaur teeth reveal about their lives?",correct:"Dietary patterns and migration routes by comparing oxygen and carbon isotopes in enamel to local water and plants",options:["Only the dinosaur's age","Dietary patterns and migration routes by comparing oxygen and carbon isotopes in enamel to local water and plants","Their speed","Their coloration"],fact:"Isotope studies showed some giant dinosaurs migrated hundreds of miles seasonally — following vegetation cycles exactly like modern wildebeest and caribou migrations!"},
    {q:"How did flowering plants in the Cretaceous affect herbivorous dinosaurs?",correct:"New plant food sources may have driven diversification of duck-billed hadrosaurs and horned ceratopsians",options:["It had no effect","New plant food sources may have driven diversification of duck-billed hadrosaurs and horned ceratopsians","All herbivores went extinct","Only meat-eaters benefited"],fact:"Hadrosaurs had hundreds of replacement teeth arranged in a dental battery — perfectly evolved for processing tough flowering plants that appeared in the Cretaceous!"},
    {q:"What is the current scientific debate about Spinosaurus's lifestyle?",correct:"Evidence suggests it was semi-aquatic, hunting fish in rivers, with dense bones for buoyancy control — unlike any other large theropod",options:["It was fully land-based","Evidence suggests it was semi-aquatic, hunting fish in rivers, with dense bones for buoyancy control — unlike any other large theropod","It lived fully in the ocean","It was an herbivore"],fact:"Recent bone density studies showed Spinosaurus bones were solid like a penguin's — built for diving rather than floating, confirming its aquatic hunting lifestyle!"},
    {q:"What was Sinosauropteryx and why was its discovery important?",correct:"The first non-avian dinosaur found with clear evidence of feathers, discovered in China in 1996",options:["The first T-Rex species","The first non-avian dinosaur found with clear evidence of feathers, discovered in China in 1996","The largest dinosaur ever","The oldest dinosaur ever"],fact:"Sinosauropteryx even preserved evidence of reddish-brown and white banded coloration — we can tell what colors this 130-million-year-old creature was!"},
    {q:"How do trackways at sites like the Paluxy River contribute to understanding dinosaur behavior?",correct:"They show sauropod and theropod tracks together, suggesting predator-prey interactions or shared habitat",options:["They prove humans and dinosaurs coexisted","They show sauropod and theropod tracks together, suggesting predator-prey interactions or shared habitat","They only show sauropod tracks","They are all fakes"],fact:"One Paluxy trackway appears to show a large theropod following a sauropod — possibly stalking prey across an ancient Texas riverbed 113 million years ago!"},
    {q:"What is taphonomy and why does it affect how we interpret dinosaur assemblages?",correct:"The study of how organisms decay and become fossils determines whether animals actually lived together or were mixed by floods or rivers after death",options:["Context is irrelevant","The study of how organisms decay and become fossils determines whether animals actually lived together or were mixed by floods or rivers after death","Only the fossils themselves matter","Age alone determines interpretation"],fact:"Some dramatic 'combat' fossil scenes are actually animals that died separately and were washed together by ancient floods — careful taphonomy reveals the true story!"},
    {q:"What role did a land bridge between Asia and North America play in dinosaur evolution?",correct:"It allowed dinosaur species to migrate between continents in both directions, including the ancestors of T-Rex coming from Asia",options:["No land bridge existed","It allowed dinosaur species to migrate between continents in both directions, including the ancestors of T-Rex coming from Asia","Only birds migrated across","Only plant-eaters crossed"],fact:"The T-Rex family (Tyrannosauridae) likely originated in Asia and migrated to North America, then evolved into the giant apex predator we know so well today!"},
    {q:"What does the Solnhofen Limestone tell us about Late Jurassic ecosystems?",correct:"It preserved exceptional fossils including Archaeopteryx in fine-grained limestone that captured delicate feathers and soft tissues",options:["It only contains rocks","It preserved exceptional fossils including Archaeopteryx in fine-grained limestone that captured delicate feathers and soft tissues","It's where T-Rex fossils come from","It only has plant fossils"],fact:"The Solnhofen Limestone formed in a shallow lagoon in Germany 150 million years ago — low-oxygen conditions prevented decay, preserving creatures in incredible detail."},
    {q:"What competing hypotheses exist for Stegosaurus plate function?",correct:"Thermoregulation, display, and species recognition are the three main competing hypotheses still debated today",options:["Plates were only for defense","Plates were only decoration","Thermoregulation, display, and species recognition are the three main competing hypotheses still debated today","Plates were for camouflage"],fact:"Blood vessel patterns in Stegosaurus plates support thermoregulation — blood could flow through them to dump excess heat or warm a cold animal in morning sun!"},
    {q:"How did evolution of warm-bloodedness potentially advantage dinosaurs?",correct:"If warm-blooded, dinosaurs could be active in cooler temperatures and at night, giving competitive advantages over cold-blooded prey and rivals",options:["It had no advantage","If warm-blooded, dinosaurs could be active in cooler temperatures and at night, giving competitive advantages over cold-blooded prey and rivals","Cold-blooded dinosaurs were more successful","Warm-bloodedness never evolved in dinosaurs"],fact:"Evidence from bone structure strongly suggests most dinosaurs had intermediate or full warm-bloodedness — much more like modern birds than like modern lizards!"},
    {q:"What is the significance of Dreadnoughtus schrani for understanding maximum dinosaur size?",correct:"At an estimated 65 tons and 85 feet long, it is one of the most complete giant sauropod specimens, allowing accurate size estimates",options:["It was actually small","At an estimated 65 tons and 85 feet long, it is one of the most complete giant sauropod specimens, allowing accurate size estimates","Its size is totally disputed","It was not a sauropod"],fact:"Dreadnoughtus was named after the battleship class because it 'feared nothing' — so massive that adult individuals had virtually no natural predators!"},
    {q:"What is the current evidence base for T-Rex's locomotion speed?",correct:"Biomechanical models of leg muscles and bones suggest walking at about 12 mph — fast enough to chase most prey, but not sprinting",options:["T-Rex was very slow","Biomechanical models of leg muscles and bones suggest walking at about 12 mph — fast enough to chase most prey, but not sprinting","T-Rex ran at 45 mph","Speed cannot be estimated from fossils"],fact:"A 2021 study of T-Rex trackways also supports this moderate walking speed — fast enough to catch most dinosaurs of its time, which were also not built for speed!"},
    {q:"How does the study of dinosaur parasites inform our understanding of their biology?",correct:"Amber-preserved ticks found on dinosaur feathers reveal details about ancient ecosystems and dinosaur health",options:["Parasites are never preserved","Amber-preserved ticks found on dinosaur feathers reveal details about ancient ecosystems and dinosaur health","Only water-dwelling species had parasites","This research is impossible"],fact:"A 2017 discovery found a 99-million-year-old tick in amber still attached to a dinosaur feather — a direct preserved link between a parasite and its dinosaur host!"},
    {q:"What is the paleogeographic distribution of ankylosaurs and what does it reveal?",correct:"Ankylosaurs lived on multiple continents and evolved distinct regional forms as continental separation drove different evolutionary paths",options:["Only found in North America","Ankylosaurs lived on multiple continents and evolved distinct regional forms as continental separation drove different evolutionary paths","Only in Asia","Only in the Southern Hemisphere"],fact:"Asian and North American ankylosaurs evolved different tail club designs separately — a beautiful example of how isolation on different continents leads to parallel but different evolutionary solutions!"},
    {q:"What are the most significant current unanswered questions in dinosaur paleontology?",correct:"Questions include exact T-Rex behavior, coloration of most species, detailed social structures, and the precise extinction timeline",options:["All questions are answered","Questions include exact T-Rex behavior, coloration of most species, detailed social structures, and the precise extinction timeline","Only dating questions remain","Only size questions remain"],fact:"Every year scientists name dozens of new dinosaur species — we are still in a golden age of discovery, with vast numbers of species yet to be found!"},
    {q:"How does artificial intelligence contribute to modern paleontology?",correct:"AI helps analyze thousands of fossil images, identify new species patterns, and reconstruct complete skeletons from partial remains",options:["AI is not used in paleontology","AI helps analyze thousands of fossil images, identify new species patterns, and reconstruct complete skeletons from partial remains","AI only makes dinosaur movies","AI only dates fossils"],fact:"Machine learning algorithms trained on known fossils can now identify species from small fragments that human paleontologists might classify as unidentifiable!"},
    {q:"What does evidence from the Kem Kem beds of Morocco reveal about Cretaceous North Africa?",correct:"An ecosystem dominated by multiple giant predators simultaneously — unlike any modern ecosystem on Earth",options:["North Africa had few dinosaurs","An ecosystem dominated by multiple giant predators simultaneously — unlike any modern ecosystem on Earth","Only herbivore fossils were found","Fossils are too poorly preserved there"],fact:"Spinosaurus, Carcharodontosaurus (larger than T-Rex!), and Deltadromaeus all lived in the same region — an extraordinary predator-dominated ecosystem we don't fully understand yet."},
    {q:"What is the significance of polar dinosaur discoveries in Alaska and Antarctica?",correct:"They show dinosaurs survived months of winter darkness, suggesting migrations or adaptations for low-light, cool conditions",options:["No polar dinosaurs existed","They show dinosaurs survived months of winter darkness, suggesting migrations or adaptations for low-light, cool conditions","Polar regions were always tropical","All polar dinosaurs were small"],fact:"Prince Creek Formation in Alaska has produced hadrosaurs, tyrannosaurs, and ceratopsians — these animals somehow thrived at high latitudes with months of winter darkness!"},
    {q:"How do pathologies in dinosaur fossils provide insight into their lives?",correct:"Healed injuries, infections, and tumors in fossils show dinosaurs lived with chronic conditions, survived serious wounds, and fought rivals",options:["Dinosaurs were always perfectly healthy","Healed injuries, infections, and tumors in fossils show dinosaurs lived with chronic conditions, survived serious wounds, and fought rivals","Pathologies are too rare to study","Only predators show injuries"],fact:"T-Rex specimens show healed bite wounds from other T-Rexes — direct physical evidence of fighting behavior within the species for territory or mating rights!"},
    {q:"What was the competitive relationship between large tyrannosaurids and earlier giant predators?",correct:"Tyrannosaurids likely outcompeted earlier apex predators over time, becoming dominant after giants like Allosaurus declined",options:["They always cooperated","Tyrannosaurids likely outcompeted earlier apex predators over time, becoming dominant after giants like Allosaurus declined","All large predators coexisted equally forever","Tyrannosaurids were never the top predators"],fact:"Before T-Rex rose to dominance, Allosaurus ruled the Late Jurassic. It took millions of years for tyrannosaurs to evolve to their enormous apex predator size."},
  ],
  "5th Grade": [
    {q:"How do molecular clocks using bird and reptile DNA help date dinosaur divergences?",correct:"Mutation rates in modern relatives are used to estimate when dinosaur lineages separated, calibrated against the fossil record",options:["Molecular clocks are not used for dinosaurs","Mutation rates in modern relatives are used to estimate when dinosaur lineages separated, calibrated against the fossil record","DNA directly preserves in all fossils","Only radiocarbon dating is used"],fact:"Molecular clock studies have revealed previously unknown dinosaur lineages that left no fossil record — their genetic legacy survives in modern birds!"},
    {q:"What is the extended phylogenetic bracket method in dinosaur soft tissue reconstruction?",correct:"By studying soft tissues in the closest living relatives (birds and crocodilians), scientists infer what soft tissues dinosaurs likely had",options:["A fossil preparation technique","By studying soft tissues in the closest living relatives (birds and crocodilians), scientists infer what soft tissues dinosaurs likely had","A CT scanning method","A museum display technique"],fact:"Using this method, scientists have reconstructed dinosaur muscle anatomy, organ systems, and even likely vocalizations from studying how their living relatives are built!"},
    {q:"How has the discovery of four-winged dinosaurs like Microraptor changed flight evolution models?",correct:"Four-winged dinosaurs suggest flight may have evolved from trees down (gliding first) rather than ground up — though the debate continues",options:["It changed nothing","Four-winged dinosaurs suggest flight may have evolved from trees down (gliding first) rather than ground up — though the debate continues","It proved ground-up flight evolution","It disproved bird evolution from dinosaurs"],fact:"Microraptor had flight feathers on all four limbs, capable of gliding between trees — the exact ancestor of powered flapping flight is still vigorously debated among paleontologists!"},
    {q:"What does stable isotope analysis of sauropod teeth reveal about their feeding ecology?",correct:"Carbon isotopes show forest vs. open-habitat feeding; oxygen isotopes reveal water sources and whether they migrated seasonally",options:["Only their age","Carbon isotopes show forest vs. open-habitat feeding; oxygen isotopes reveal water sources and whether they migrated seasonally","Their speed","Their coloration"],fact:"Some giant sauropods traveled between lowland floodplains and upland forests seasonally, following vegetation cycles — like modern elephant migrations but on an even larger scale!"},
    {q:"What did eggshell chemistry analyses using clumped isotopes reveal about dinosaur physiology?",correct:"Eggshell mineral chemistry indicates dinosaur eggs were incubated at warm-blooded temperatures, confirming endothermy",options:["Dinosaurs were cold-blooded based on eggs","Eggshell mineral chemistry indicates dinosaur eggs were incubated at warm-blooded temperatures, confirming endothermy","Eggshell tells us nothing about physiology","Only bird eggs can be analyzed"],fact:"This 2020 discovery was a landmark confirmation of dinosaur warm-bloodedness — the chemistry of their eggshells matched modern warm-blooded animals, not cold-blooded ones!"},
    {q:"How does biogeographic analysis help determine the origin of dinosaur groups?",correct:"By mapping earliest fossil occurrences and ancient plate tectonic positions, scientists reconstruct where each dinosaur group first evolved",options:["Biogeography is not used for dinosaurs","By mapping earliest fossil occurrences and ancient plate tectonic positions, scientists reconstruct where each dinosaur group first evolved","All dinosaurs originated in Africa","All dinosaurs originated in North America"],fact:"Biogeographic analysis suggests dinosaurs as a group originated in South America and spread globally over tens of millions of years as Pangaea began breaking apart!"},
    {q:"What are the implications of gregarious behavior in ceratopsians for understanding Cretaceous ecology?",correct:"Large ceratopsian herds would have been major ecosystem engineers, heavily shaping vegetation and creating habitats for other species",options:["Herds had no ecological impact","Large ceratopsian herds would have been major ecosystem engineers, heavily shaping vegetation and creating habitats for other species","Ceratopsians were always solitary","Only small dinosaurs lived in groups"],fact:"Centrosaurus bone beds contain thousands of individuals — evidence of massive migratory herds that shaped entire Cretaceous landscapes the way bison shaped the American Great Plains!"},
    {q:"What is the current understanding of how Velociraptor's sickle claw was used?",correct:"Biomechanical analysis suggests the claw pinned prey by gripping it, while the jaws delivered the killing bite",options:["The claw disemboweled prey","Biomechanical analysis suggests the claw pinned prey by gripping it, while the jaws delivered the killing bite","The claw was only for defense","Velociraptors had no specialized weapons"],fact:"This revised understanding came from comparing the sickle claw to modern raptors like eagles, which use their talons to grip and hold struggling prey while biting — not slashing."},
    {q:"How does the study of trace fossils differ methodologically from body fossil analysis?",correct:"Trace fossils record behavior directly but cannot be assigned to a species without associated body fossils; they require specialized ichnological analysis",options:["They use identical methods","Trace fossils record behavior directly but cannot be assigned to a species without associated body fossils; they require specialized ichnological analysis","Trace fossils are less informative","Only body fossils are scientifically valid"],fact:"Ichnology (the science of trace fossils) has its own naming system separate from species names — the same animal can have different ichnological names for its footprints, burrows, and nests!"},
    {q:"What do melanosomes in dinosaur feather fossils reveal?",correct:"Preserved pigment organelles compared to modern bird melanosomes allow reconstruction of actual feather colors",options:["Color cannot be determined from fossils","Preserved pigment organelles compared to modern bird melanosomes allow reconstruction of actual feather colors","All dinosaurs were gray","Color is guessed from related species"],fact:"The dinosaur Anchiornis was reconstructed with a mostly black body, reddish crown, and white wing patches — we know what it looked like 160 million years ago!"},
    {q:"How does sedimentological context affect interpretation of dinosaur fossil assemblages?",correct:"Rock type and depositional environment reveal whether animals lived together or were transported and mixed after death by water",options:["Context doesn't matter","Rock type and depositional environment reveal whether animals lived together or were transported and mixed after death by water","Only the fossils matter","Age alone determines interpretation"],fact:"Some dramatic fossil scenes of 'battling' dinosaurs are actually animals that died separately and were washed together by ancient floods — taphonomy reveals the true story."},
    {q:"What evolutionary innovations allowed sauropods to achieve extraordinary body size?",correct:"Pneumatized vertebrae, columnar limbs, efficient one-way breathing, high-fiber plant diet processing, and rapid growth rates all combined to enable giant size",options:["Only genetic size factors","Pneumatized vertebrae, columnar limbs, efficient one-way breathing, high-fiber plant diet processing, and rapid growth rates all combined to enable giant size","Unknown mechanisms","They grew slowly over centuries"],fact:"A sauropod might gain 5,000 pounds per year during peak growth — a rate impossible for mammals but enabled by this unique suite of physiological adaptations working together."},
    {q:"What is the current debate about whether the K-Pg asteroid or Deccan volcanism was more responsible for dinosaur extinction?",correct:"Most evidence supports the asteroid as the primary driver, but Deccan volcanism may have weakened ecosystems beforehand — both likely contributed",options:["Only the asteroid mattered","Only volcanism mattered","Most evidence supports the asteroid as the primary driver, but Deccan volcanism may have weakened ecosystems beforehand — both likely contributed","Neither caused the extinction"],fact:"The iridium layer found worldwide at the K-Pg boundary — rare on Earth but common in asteroids — is the strongest evidence that an extraterrestrial impact was the primary extinction driver."},
    {q:"How does the concept of ecological succession apply to post-K-Pg recovery of life?",correct:"As dinosaur ecological roles vacated, mammals, birds, and other survivors gradually filled herbivore, predator, and other niches over millions of years",options:["Recovery was immediate","As dinosaur ecological roles vacated, mammals, birds, and other survivors gradually filled herbivore, predator, and other niches over millions of years","No recovery occurred","Dinosaurs were replaced identically"],fact:"It took mammals about 10-15 million years to evolve to the same large body sizes that dinosaurs had achieved — evolution is slow, even given empty ecological niches to fill!"},
    {q:"What is the evo-devo perspective on why ceratopsian species evolved such different frill shapes so rapidly?",correct:"Small mutations in developmental gene expression timing can produce dramatically different frill shapes — development is highly evolvable",options:["Frills evolved by chance alone","Small mutations in developmental gene expression timing can produce dramatically different frill shapes — development is highly evolvable","All frills evolved identically","Frills are unrelated to genetics"],fact:"This explains why dozens of ceratopsian species could evolve dramatically different headgear so rapidly in geological time — developmental biology is exceptionally responsive to selection pressure!"},
    {q:"Why can true dinosaur DNA not be recovered from fossils?",correct:"DNA decays within about 1 million years even in ideal conditions — all non-bird dinosaur fossils are far too old for DNA preservation",options:["Dinosaur DNA has been partially sequenced","DNA decays within about 1 million years even in ideal conditions — all non-bird dinosaur fossils are far too old for DNA preservation","DNA is preserved in all fossils","Dinosaur DNA is regularly recovered"],fact:"Claims of recovered dinosaur DNA have been repeatedly shown to be contamination or misidentification. The real dinosaur genetic legacy lives in birds — their direct descendants!"},
    {q:"What do non-dinosaurian dinosauriform relatives like Lagerpeton reveal about dinosaur origins?",correct:"They reveal a gradual evolutionary progression of dinosaur features rather than dinosaurs appearing suddenly fully formed",options:["They disprove evolution","They reveal a gradual evolutionary progression of dinosaur features rather than dinosaurs appearing suddenly fully formed","Dinosaurs appeared suddenly","These animals are unrelated to dinosaurs"],fact:"Lagerpeton and Marasuchus from the Triassic show intermediate features between dinosaurs and their archosaur ancestors — evolution caught in the act of producing a completely new animal group!"},
    {q:"How does the study of dinosaur pathologies (injuries and diseases) inform our understanding of their social behavior?",correct:"Healed injuries from conspecifics (same species) suggest intraspecific combat for territory and mates, indicating complex social dynamics",options:["Dinosaurs never fought each other","Healed injuries from conspecifics (same species) suggest intraspecific combat for territory and mates, indicating complex social dynamics","Pathologies tell us nothing about behavior","Only predator injuries can be identified"],fact:"T-Rex specimens with healed T-Rex bite marks suggest these apex predators fought each other regularly — likely competing over mates, territory, and food, just like modern large predators do."},
    {q:"What is the significance of recently discovered giant sauropod Patagotitan mayorum?",correct:"One of the most complete giant titanosaur specimens ever found, allowing unprecedented accuracy in size estimates for the largest known land animal",options:["It was actually medium-sized","One of the most complete giant titanosaur specimens ever found, allowing unprecedented accuracy in size estimates for the largest known land animal","Its size remains completely unknown","It disproved previous size records"],fact:"Patagotitan's femur bone alone is 8 feet tall — taller than most humans. This Argentinian dinosaur lived 100 million years ago and weighed an estimated 69 tons!"},
    {q:"How does the field of paleobiology use living organisms as analogues for extinct dinosaurs?",correct:"By studying how modern animals with similar body plans, diets, and lifestyles function, scientists build evidence-based models of dinosaur biology and behavior",options:["Modern animals are irrelevant","By studying how modern animals with similar body plans, diets, and lifestyles function, scientists build evidence-based models of dinosaur biology and behavior","Only bird analogues are useful","This method is considered unreliable"],fact:"Ostriches are used to model bipedal dinosaur locomotion; elephants to model giant herbivore feeding; crocodilians to model archosaur nest-guarding behavior — all grounded in evolutionary relatedness!"},
    {q:"What is the current scientific understanding of dinosaur intelligence relative to modern animals?",correct:"Most non-avian dinosaurs were probably comparable to modern reptiles in intelligence, but some theropods may have been as intelligent as modern birds",options:["All dinosaurs were as smart as dolphins","Most non-avian dinosaurs were probably comparable to modern reptiles in intelligence, but some theropods may have been as intelligent as modern birds","All dinosaurs were unintelligent","Intelligence cannot be studied from fossils"],fact:"A controversial 2023 study suggested some large theropods had neuron densities comparable to primates — though most paleontologists think the evidence for high intelligence remains limited and speculative."},
    {q:"How does the concept of character displacement apply to communities of dinosaur predators?",correct:"Predator species living together evolved to exploit different prey sizes and types, reducing direct competition — similar to what is seen in modern predator communities",options:["Predators always competed directly","Predator species living together evolved to exploit different prey sizes and types, reducing direct competition — similar to what is seen in modern predator communities","Only one large predator could exist at a time","All predators ate the same prey"],fact:"In Cretaceous North America, T-Rex (large prey), Troodon (small prey), and various medium-sized predators each occupied different predatory niches — reducing the direct competition that would otherwise eliminate weaker competitors."},
  ],
};

